package com.yeyamo_mobile.api.notification_service.infrastructure.messaging;
import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.ParameterizedTypeReference;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class UserActivityClient{private final RestClient client;private final String token;public UserActivityClient(RestClient.Builder b,@Value("${yeyamo.services.user.url:http://user-service:8080}")String url,@Value("${yeyamo.security.internal-token:}")String token){client=b.baseUrl(url).build();this.token=token;}public List<String> inactive(Instant before,int limit){if(token.isBlank())throw new IllegalStateException("INTERNAL_SERVICE_TOKEN_REQUIRED");var value=client.get().uri(u->u.path("/internal/users/inactive").queryParam("before",before).queryParam("limit",limit).build()).header("X-Internal-Token",token).retrieve().body(new ParameterizedTypeReference<List<String>>(){});return value==null?List.of():value;}}
